-- treaty MU-LU ← mra-MU-dta
insert into treaty (country_a, country_b, status, mli_note, wht_dividend, wht_interest, source_url, verified_on, next_check_on, signed_on, in_force_on) values ('MU', 'LU', 'in_force', 'Treaty WHT from Mauritius: dividends 5% and 10%, interest and royalties exempt (MRA table). Signed 15 Feb 1995, protocol of 28 Jan 2014, MLI in force for Mauritius 1 Feb 2020; applicable in Luxembourg from 1 Jan 1996 (Luxembourg treaty list, Mémorial A n° 24 of 1996). Exact entry-into-force date to confirm.', 10, 0, 'https://www.mra.mu/taxes-duties/international-taxation/double-taxation-agreements', '2026-10-03', '2027-03-31', '1995-02-15', null) on conflict (country_a, country_b) do update set status = excluded.status, mli_note = coalesce(excluded.mli_note, treaty.mli_note), source_url = excluded.source_url, verified_on = excluded.verified_on, next_check_on = excluded.next_check_on, wht_dividend = coalesce(excluded.wht_dividend, treaty.wht_dividend), wht_interest = coalesce(excluded.wht_interest, treaty.wht_interest), signed_on = coalesce(excluded.signed_on, treaty.signed_on), in_force_on = coalesce(excluded.in_force_on, treaty.in_force_on);
-- treaty SC-LU ← src-SC-dta
insert into treaty (country_a, country_b, status, mli_note, wht_dividend, wht_interest, source_url, verified_on, next_check_on, signed_on, in_force_on) values ('SC', 'LU', 'in_force', 'Signed in Luxembourg on 4 Jun 2012; entered into force on 19 Aug 2013 (Mémorial A n° 168 of 13 Sep 2013, p. 3214); applicable from 1 Jan 2014 (Luxembourg treaty list). Listed on the SRC agreements page. Treaty WHT rates not yet read.', null, null, 'https://impotsdirects.public.lu/dam-assets/fr/legislation/legi13/M__morial_A_-_N___168_du_13_septembre_2013.pdf', '2026-10-03', '2027-03-31', '2012-06-04', '2013-08-19') on conflict (country_a, country_b) do update set status = excluded.status, mli_note = coalesce(excluded.mli_note, treaty.mli_note), source_url = excluded.source_url, verified_on = excluded.verified_on, next_check_on = excluded.next_check_on, wht_dividend = coalesce(excluded.wht_dividend, treaty.wht_dividend), wht_interest = coalesce(excluded.wht_interest, treaty.wht_interest), signed_on = coalesce(excluded.signed_on, treaty.signed_on), in_force_on = coalesce(excluded.in_force_on, treaty.in_force_on);
-- gate LU blacklist MU ← lu-nc-list
